            'the byte floor',
      );
    });

    test(
      'fixture (RED of #1275): directory structure WITHOUT the SKILL.md '
      'content fails — one verdict per hollow skill',
      () async {
        final tmp = await Directory.systemTemp.createTemp(
          'builtin_skill_guard',
